def breadcrumbs(items: list[tuple[str,str|None]], home:bool=False):
    out=[]
    for label,link in [('홈',url('index.html',home))]+items:
        out.append(f'<a href="{link}">{escape(label)}</a>' if link else f'<span aria-current="page">{escape(label)}</span>')
    return '<nav class="breadcrumbs" aria-label="현재 위치">'+'<span aria-hidden="true">/</span>'.join(out)+'</nav>'


def wrap(filename,title,active,content,home=False,crumb=None,theme='paper'):
    # Resolve explicitly authored component calls embedded in non-f-string HTML fragments.
    content = re.sub(r"\{eyebrow\('([^']+)'\)\}", lambda m: eyebrow(m.group(1)), content)
    content = re.sub(r"\{blocklink\('([^']+)','([^']+)','([^']+)'\)\}", lambda m: blocklink(*m.groups()), content)
    assets= 'assets/' if home else '../assets/'
    head = f'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="color-scheme" content="light"><title>{escape(title)} | 약국오늘 CITY SIGNAL 디자인 시안</title><meta name="description" content="약국오늘 CITY SIGNAL 리디자인 시안 — 실제 서비스 데이터와 연결되지 않은 검토용 정적 HTML"><link rel="stylesheet" href="{assets}design.css"><script defer src="{assets}design.js"></script></head>
<body><div class="site">{nav_html(active,home)}<div class="demo-bar">DESIGN PROTOTYPE / 실제 약국·의약품 정보, 영업 상태, 의료 정보, 검색 결과와 연결되지 않은 디자인 목업입니다.</div>'''
    if crumb: head+=breadcrumbs(crumb,home)
    html=head+f'<main id="main">{content}</main>'+footer_html(home)+'<div class="toast" role="status" aria-live="polite" hidden data-toast></div></div></body></html>'
    path=ROOT/filename if home else PAGES/filename
    path.write_text(html,encoding='utf-8')
    return path


def sample_item(i:int, *, home:bool=False):
    distance=[.4,1.2,2.8,4.5][i-1] if i<=4 else 6.6
    closing=[180,70,210,40][i-1] if i<=4 else 90
    labels=['가상 예시약국 A','가상 예시약국 B','가상 예시약국 C','가상 예시약국 D']
    name=labels[i-1] if i<=4 else '가상 예시약국 E'
    page=url('pharmacy.html',home)
    return f'''<article class="directory-item" data-sample-distance="{distance}" data-sample-close="{closing}"><div><span class="status status-demo">목업 예시 · 실제 영업 미확인</span><h3><a href="{page}">{name}</a></h3><p class="meta">서울 지역 · 가상 표기　/　운영시간과 전화번호는 실제 연동 후 표시</p><div class="small-note">실제 주소·연락처·재고 정보가 아닙니다.</div></div><div class="actions"><span class="distance">{distance:g} km <span class="micro">/ 가상 거리</span></span>{blocklink('정보 보기',page,'btn btn-small btn-outline')}</div></article>'''


